using System;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Diagnostics;using System.Threading.Tasks;using System.Web.Script.Serialization;

sealed class Feature {public string id,title,group,kind,scope,body,modifier,arg,description,trait;public string[] contains;public int value;public bool other,mass,repeat,requiresPack,v2;public override string ToString(){return title;}}
sealed class CatalogItem {public string id,name,group;public override string ToString(){return name+"  ·  "+id+(String.IsNullOrEmpty(group)?"":"  ·  "+group);}}
sealed class Person {public uint ID;public string Name,Role,Details;public override string ToString(){return Lang.T(Name)+"  ["+ID+"] · "+Lang.Role(Role);}}
sealed class Snapshot {public string Name,Metrics,Government;public uint Player;public long PlayerPointer;public List<Person> People=new List<Person>();public List<CatalogItem> Provinces=new List<CatalogItem>();}

static class Templates {
 public static List<Feature> Features;public static Dictionary<string,List<CatalogItem>> Catalogs;
 public static void Load(string root){var j=new JavaScriptSerializer{MaxJsonLength=20000000};Features=j.Deserialize<List<Feature>>(File.ReadAllText(Path.Combine(root,"features.json")));Catalogs=j.Deserialize<Dictionary<string,List<CatalogItem>>>(File.ReadAllText(Path.Combine(root,"catalogues.json")));Lang.Localize(Features);Lang.Localize(Catalogs);foreach(var f in Features){if(!Regex.IsMatch(f.id,"^[a-z0-9_]+$"))throw new InvalidDataException(Lang.T("Неверный ID функции."));if(f.kind=="toggle" && f.modifier!="ck3t_"+f.id)throw new InvalidDataException(Lang.T("Неверное имя личного бонуса."));}}
 public static bool Realm;
 public static string Dirty="if = { limit = { NOT = { is_target_in_global_variable_list = { name = ck3t_dirty target = this } } } add_to_global_variable_list = { name = ck3t_dirty target = this } }";
 public static string Flush="every_in_global_list = { variable = ck3t_dirty scriptedtests_recalculate_character_modifier = yes force_character_skill_recalculation = yes debug_log = \"CK3T_RECALC\" } clear_global_variable_list = ck3t_dirty";
 public static string Expand(string text,string player){
  foreach(string macro in new[]{"FAMILY","COUNTIES","PROVINCES","RULERS"}){string needle="$"+macro+"{";int at;
   while((at=text.IndexOf(needle,StringComparison.Ordinal))>=0){int depth=1,end=at+needle.Length;for(;end<text.Length && depth>0;end++){if(text[end]=='{')depth++;if(text[end]=='}')depth--;}if(depth!=0)throw new InvalidDataException(Lang.T("Незакрытый шаблон."));string inner=text.Substring(at+needle.Length,end-at-needle.Length-1),replacement;
    if(macro=="FAMILY")replacement=inner+" every_spouse = { limit = { is_alive = yes } "+inner+" } every_child = { limit = { is_alive = yes } "+inner+" }";
    else if(macro=="COUNTIES")replacement="every_sub_realm_county = { "+(Realm?"":"limit = { holder = global_var:"+player+" } ")+inner+" }";
    else if(macro=="RULERS")replacement=inner+(Realm?" every_vassal_or_below = { "+inner+" }":"");
    else replacement="every_sub_realm_county = { every_county_province = { "+(Realm?"":"limit = { barony.holder = global_var:"+player+" } ")+inner+" } }";
    text=text.Substring(0,at)+replacement+text.Substring(end);
   }
  }return text;
 }
 public static string Scope(Feature f,string inner){if(f.scope=="knights")return "every_knight = { "+inner+" }";if(f.scope=="family")return "$FAMILY{ "+inner+" }";if(f.scope=="rulers")return "$RULERS{ "+inner+" }";if(f.scope=="counties")return "$COUNTIES{ "+inner+" }";if(f.scope=="provinces")return "$PROVINCES{ "+inner+" }";if(f.scope=="commanders")return "every_army = { if = { limit = { exists = army_commander } army_commander = { "+inner+" } } }";return inner;}
 public static string ModifierType(Feature f){return f.scope=="counties"?"county":f.scope=="provinces"?"province":"character";}
 static string Remove(Feature f){return f.kind=="guard"?"if = { limit = { has_trait = "+f.trait+" } remove_trait = "+f.trait+" "+Dirty+" }":"if = { limit = { has_"+ModifierType(f)+"_modifier = "+f.modifier+" } remove_"+ModifierType(f)+"_modifier = "+f.modifier+" "+(ModifierType(f)=="character"?Dirty:"")+" }";}
 public static string Disable(Feature f){return "every_in_global_list = { variable = ck3t_active_"+f.id+" "+Remove(f)+" } clear_global_variable_list = ck3t_active_"+f.id;}
 public static string Enable(Feature f){string type=ModifierType(f),has=f.kind=="guard"?"has_trait = "+f.trait:"has_"+type+"_modifier = "+f.modifier;
  string add=f.kind=="guard"?"add_trait = "+f.trait:"add_"+type+"_modifier = { modifier = "+f.modifier+" }";
  string inner="if = { limit = { NOT = { "+has+" } } "+add+" "+(type=="character"?Dirty:"")+" add_to_global_variable_list = { name = ck3t_active_"+f.id+" target = this } debug_log = \"CK3T_NEW:"+f.id+"\" } if = { limit = { "+has+" } debug_log = \"CK3T_APPLIED:"+f.id+"\" }";
  return Expand(Scope(f,inner),"ck3t_context_player");
 }
 public static string Reconcile(Feature f){string next="ck3t_next_"+f.id;
  string candidates=Expand(Scope(f,"add_to_global_variable_list = { name = "+next+" target = this }"),"ck3t_context_player");
  return "clear_global_variable_list = "+next+" "+candidates+" every_in_global_list = { variable = ck3t_active_"+f.id+" if = { limit = { NOT = { is_target_in_global_variable_list = { name = "+next+" target = this } } } "+Remove(f)+" remove_list_global_variable = { name = ck3t_active_"+f.id+" target = this } } } "+Enable(f).Replace("debug_log = \"CK3T_APPLIED:"+f.id+"\"","")+" clear_global_variable_list = "+next;
 }
 public static string Body(Feature f,int amount,string key,uint province){
  if(f.arg!=""){if(!Catalogs.ContainsKey(f.arg) || !Catalogs[f.arg].Any(x=>x.id==key))throw new InvalidOperationException(Lang.T("Выбери объект из справочника."));if(!Regex.IsMatch(key,"^[a-zA-Z0-9_]+$"))throw new InvalidDataException(Lang.T("Неверный ID объекта."));}
  string template=f.body;if(Realm && (f.id=="building" || f.id=="special"))template=template.Replace("holder = global_var:$PLAYER","OR = { holder = global_var:$PLAYER barony.holder = { is_vassal_or_below_of = global_var:$PLAYER } }");if((f.id=="gold" || f.id=="target_gold") && amount<0)template="remove_short_term_gold = $V";if(!f.v2 && f.scope=="family" && template.Contains("$FAMILY{")){int end=template.LastIndexOf('}');template=template.Insert(end,Dirty);}else if(f.id.StartsWith("skill_") || f.id.StartsWith("trait_") || new[]{"target_weak","target_ill","target_heal","target_trait_remove"}.Contains(f.id))template+=" "+Dirty;
  int effective=(f.id=="gold" || f.id=="target_gold")?Math.Abs(amount):amount;string body=Expand(template,"ck3t_context_player").Replace("$DIRTY",Dirty).Replace("$PERCENT",(amount/100.0).ToString(System.Globalization.CultureInfo.InvariantCulture)).Replace("$V",effective.ToString(System.Globalization.CultureInfo.InvariantCulture)).Replace("$KEY",key??"").Replace("$PROV",province.ToString()).Replace("$PLAYER","ck3t_context_player").Replace("$OTHER","ck3t_context_other");if(body.Contains("$"))throw new InvalidDataException(Lang.T("Неразрешённый шаблон."));return body;
 }
}

sealed class TrainerSession : IDisposable {
 public NativeBridge Bridge;public NativeProtection Protection;public NativeWarScores WarScores;public NativeSieges Sieges;public NativeCultureHeads CultureHeads;public CampaignEngine Campaign;readonly Dictionary<string,uint[]> nativeSets=new Dictionary<string,uint[]>();public Snapshot State;public readonly HashSet<string> Active=new HashSet<string>();
 public string LastReply="";public readonly string Root;public bool PackV2;public int LastNew,LastRecalculations,LastCommands;public Action<string> Progress;
 IEnumerable<Feature> Switches {get{return Templates.Features.Where(f=>(f.kind=="toggle" || f.kind=="guard") && (!f.requiresPack || PackV2));}}
 const string RootInfo="debug_log = \"CK3T_INFO|[SCOPE.GetRootScope.GetCharacter.GetID]|[SCOPE.GetRootScope.GetCharacter.GetNameNoTooltip]|[SCOPE.GetRootScope.GetCharacter.GetAge]|[SCOPE.GetRootScope.GetCharacter.GetGold]\"";
 public TrainerSession(string root){Root=root;}
 public async Task<EngineReply> Send(string body,uint id){LastReply="";var reply=await Bridge.Execute(body,id,Guid.NewGuid().ToString("N"));LastCommands++;LastReply=reply.Text;LastNew+=reply.Rows("CK3T_NEW:").Count();LastRecalculations+=reply.Rows("CK3T_RECALC").Count();if(reply.Error)throw new InvalidOperationException(Lang.T("Движок отклонил часть команды. Подробности сохранены в журнале."));return reply;}
 public async Task Connect(int pid){
  Bridge=new NativeBridge(Process.GetProcessById(pid),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),@"Paradox Interactive\Crusader Kings III\logs\debug.log"));
  try{Protection=new NativeProtection(Bridge);WarScores=new NativeWarScores(Bridge);Sieges=new NativeSieges(Bridge);CultureHeads=new NativeCultureHeads(Bridge);await CultureHeads.Recover();var r=await Send("add_character_modifier = { modifier = ck3t_probe days = 1 } if = { limit = { has_character_modifier = ck3t_probe } debug_log = \"CK3T_PACK_OK\" } remove_character_modifier = ck3t_probe",Bridge.PlayerID);if(!r.Rows("CK3T_PACK_OK").Any())throw new InvalidOperationException(Lang.T("Пакет бонусов не загружен. Установи пакет, затем самостоятельно перезапусти CK3."));var v=await Bridge.Execute("add_character_modifier = { modifier = ck3t_v2_probe days = 1 } if = { limit = { has_character_modifier = ck3t_v2_probe } debug_log = \"CK3T_V2_OK\" } remove_character_modifier = ck3t_v2_probe",Bridge.PlayerID,Guid.NewGuid().ToString("N"));PackV2=!v.Error && v.Rows("CK3T_V2_OK").Any();if(PackV2){var tr=await Bridge.Execute("if = { limit = { has_trait = ck3t_battle_shield } debug_log = \"CK3T_V2_TRAITS_OK\" } else = { add_trait = ck3t_battle_shield if = { limit = { has_trait = ck3t_battle_shield } debug_log = \"CK3T_V2_TRAITS_OK\" remove_trait = ck3t_battle_shield } }",Bridge.PlayerID,Guid.NewGuid().ToString("N"));PackV2=tr.Rows("CK3T_V2_TRAITS_OK").Any();}var mk=await Bridge.Execute("add_trait = "+NativeBridge.TargetMarker+" if = { limit = { has_trait = "+NativeBridge.TargetMarker+" } debug_log = \"CK3T_MARKER_OK\" } every_living_character = { limit = { has_trait = "+NativeBridge.TargetMarker+" } remove_trait = "+NativeBridge.TargetMarker+" }",Bridge.PlayerID,Guid.NewGuid().ToString("N"));Bridge.MarkerReady=!mk.Error && mk.Rows("CK3T_MARKER_OK").Any();await Clear();await ReadSnapshot(false);Campaign=new CampaignEngine(this,Root);await Campaign.Stories.Restore();}catch{Dispose();throw;}
 }
 public async Task<Snapshot> ReadSnapshot(bool broad){
  Bridge.Refresh();uint player=Bridge.PlayerID;
  string body=RootInfo+" debug_log = \"CK3T_GOV|[SCOPE.GetRootScope.GetCharacter.GetGovernment.GetName]\" set_global_variable = { name = ck3t_context_player value = this } ";
  foreach(var role in new[]{new[]{"every_spouse","Супруг"},new[]{"every_child","Ребёнок"},new[]{"every_vassal_or_below","Вассал"},new[]{"every_courtier","Придворный"}}){if(!broad && (role[0]=="every_vassal_or_below" || role[0]=="every_courtier"))continue;body+=role[0]+" = { limit = { is_alive = yes } debug_log = \"CK3T_ROLE:"+role[1]+"\" debug_log_scopes = no } ";}
  body+=Templates.Expand("$PROVINCES{ debug_log = \"CK3T_HOLDING\" debug_log_scopes = no }","ck3t_context_player")+" remove_global_variable = ck3t_context_player";
  var r=await Send(body,player);var snapshot=new Snapshot{Player=player,PlayerPointer=Bridge.PlayerPointer};string info=r.Rows("CK3T_INFO|").LastOrDefault();if(info==null)throw new InvalidOperationException(Lang.T("Не удалось прочитать правителя."));string[] p=info.Split('|');if(p.Length<4 || p[0]!=player.ToString())throw new InvalidOperationException(Lang.T("Игровой корень не совпал с правителем."));snapshot.Name=p[1];snapshot.Metrics=Lang.T("Возраст: ")+p[2]+Lang.T("   ·   Золото: ")+p[3];snapshot.People.Add(new Person{ID=player,Name=p[1],Role="Мой правитель"});
  string current="";foreach(string line in r.Text.Split('\n')){
   if(line.Contains("jomini_effect_impl.cpp") && line.Contains("CK3T_ROLE:"))current=line.Substring(line.IndexOf("CK3T_ROLE:")+10).Trim();
   if(line.Contains("jomini_effect_impl.cpp") && line.Contains("CK3T_HOLDING"))current="Владение";
   if(!line.Contains("effectimpl.cpp:642"))continue;
   Match m=Regex.Match(line,@"\]: (.*?) \(Internal ID: (\d+) - Historical ID");uint id;
   if(m.Success && UInt32.TryParse(m.Groups[2].Value,out id) && !snapshot.People.Any(x=>x.ID==id)){string name=Regex.Replace(m.Groups[1].Value,@"_[0-9A-Fa-f]{4,6}","").Replace(" of  ","").Trim();snapshot.People.Add(new Person{ID=id,Name=name,Role=current});}

   Match prov=Regex.Match(line,@"\]: (.*?) \(Internal ID: (\d+)\).*?\(Province\s*[—-]\s*\d+\)");if(prov.Success && !snapshot.Provinces.Any(x=>x.id==prov.Groups[2].Value))snapshot.Provinces.Add(new CatalogItem{id=prov.Groups[2].Value,name=prov.Groups[1].Value.Trim()});
  }snapshot.Government=r.Rows("CK3T_GOV|").LastOrDefault()??"";State=snapshot;return snapshot;
 }
 public async Task<Person> Inspect(uint id){if(!Bridge.ValidCharacter(id))throw new InvalidOperationException(Lang.T("Персонажа с этим ID нет в кампании."));var r=await Send(RootInfo,id);string info=r.Rows("CK3T_INFO|").LastOrDefault();if(info==null)throw new InvalidOperationException(Lang.T("Нет данных цели."));string[] p=info.Split('|');if(p.Length<4 || p[0]!=id.ToString())throw new InvalidOperationException(Lang.T("Игра выбрала другую цель. Действие отменено."));return new Person{ID=id,Name=p[1],Role="Проверенная цель",Details=Lang.T("Возраст: ")+p[2]+Lang.T(" · Золото: ")+p[3]};}
 async Task Context(uint other){await Send("set_global_variable = { name = ck3t_context_player value = this }",State.Player);if(other!=0)await Send("set_global_variable = { name = ck3t_context_other value = this }",other);}
 async Task CleanContext(){Bridge.Refresh();await Send("remove_global_variable = ck3t_context_player remove_global_variable = ck3t_context_other",Bridge.PlayerID);}
 void Check(){Bridge.Refresh();if(State==null || State.Player!=Bridge.PlayerID || State.PlayerPointer!=Bridge.PlayerPointer)throw new InvalidOperationException(Lang.T("Правитель или кампания сменились. Обнови подключение перед действием."));}
 public async Task<int> Toggle(Feature f,bool on,uint target){
  if(f.requiresPack && !PackV2)throw new InvalidOperationException(Lang.T("Эта функция требует пакета 2. Он подготовлен: сохрани и вручную перезапусти игру, затем подключись снова."));
  if(f.kind=="native"){Check();var ids=on?(f.scope=="family"?(await ReadSnapshot(false)).People.Where(p=>new[]{"Мой правитель","Супруг","Ребёнок"}.Contains(p.Role)).Select(p=>p.ID).ToArray():new[]{f.scope=="target"?target:State.Player}):new uint[0];ReplaceNativeSet(f.id,ids);if(on)Active.Add(f.id);else Active.Remove(f.id);return ids.Length;}
  Check();uint id=on && f.scope=="target"?target:State.Player;if(id==0)throw new InvalidOperationException(Lang.T("Сначала выбери и проверь цель."));
  LastNew=LastRecalculations=LastCommands=0;int count=0;string conflicts="";var displaced=new List<string>();if(on)foreach(var x in Switches.Where(x=>x.id!=f.id && Active.Contains(x.id) && (f.kind=="guard" && x.kind=="guard" && x.trait==f.trait || f.contains!=null && f.contains.Contains(x.id) || x.contains!=null && x.contains.Contains(f.id))).ToList()){conflicts+=Templates.Disable(x)+" ";displaced.Add(x.id);}
  string ctx=id==State.Player?"set_global_variable = { name = ck3t_context_player value = this } ":"";if(id!=State.Player)await Context(0);
  try{var r=await Send(ctx+conflicts+(on?Templates.Enable(f):Templates.Disable(f))+" "+GuardMaintenance(f,on)+" "+Templates.Flush+" remove_global_variable = ck3t_context_player",id);foreach(string old in displaced)Active.Remove(old);count=r.Rows("CK3T_APPLIED:"+f.id).Count();if(on && count==0)throw new InvalidOperationException(Lang.T("Подходящих объектов нет. Переключатель не включён."));if(on)Active.Add(f.id);else Active.Remove(f.id);}finally{if(id!=State.Player)await CleanContext();}return count;
 }
 string GuardMaintenance(Feature f,bool on){if(!on || f.kind!="guard")return "";if(f.trait=="ck3t_disease_shield")return Templates.Expand(Templates.Scope(f,File.ReadAllText(Path.Combine(Root,"disease-cleanup.txt")).Replace("$DIRTY",Templates.Dirty)),"ck3t_context_player");if(f.trait=="ck3t_battle_shield")return "every_army = { limit = { army_commander = global_var:ck3t_context_player } remove_commander = yes }";return "";}
 public async Task Action(Feature f,int amount,string key,uint province,uint target,uint other){
  Check();uint id=f.scope=="target"?target:State.Player;if(id==0)throw new InvalidOperationException(Lang.T("Сначала проверь цель."));if(f.other && other==0)throw new InvalidOperationException(Lang.T("Выбери второго персонажа."));if((f.id=="building" || f.id=="special") && province==0)throw new InvalidOperationException(Lang.T("Выбери личное владение либо укажи ID провинции."));if(f.id=="maa_add" && (amount<1 || amount>100))throw new InvalidOperationException(Lang.T("Размер полка: от 1 до 100."));
  if(f.id=="target_birth"){
   var mother=await Send("if = { limit = { is_alive = yes is_female = yes age >= 18 } debug_log = \"CK3T_ADULT_MOTHER\" }",target);var father=await Send("if = { limit = { is_alive = yes is_female = no age >= 18 } debug_log = \"CK3T_ADULT_FATHER\" }",other);
   if(!mother.Rows("CK3T_ADULT_MOTHER").Any() || !father.Rows("CK3T_ADULT_FATHER").Any())throw new InvalidOperationException(Lang.T("Нужны живая взрослая женщина и взрослый мужчина."));Check();var reply=await Bridge.ExecuteConsole("pregnancy "+target+" "+other+" yes",target);LastReply=reply.Text;if(reply.Error)throw new InvalidOperationException(Lang.T("Движок отклонил рождение ребёнка."));return;
  }
  if(f.repeat && (amount<1 || amount>8))throw new InvalidOperationException(Lang.T("Число проходов: 1–8."));if(f.id=="enemy_deplete" && (amount<1 || amount>100))throw new InvalidOperationException(Lang.T("Процент потерь: 1–100."));
  LastNew=LastRecalculations=LastCommands=0;await Context(f.other?other:0);try{
   var bodies=new List<string>();if(f.id=="build_upgrade_all"){var clauses=Regex.Matches(f.body,@"if = \{ limit = \{ has_building = \w+ \} upgrade_building_effect = \w+ \}").Cast<Match>().Select(m=>m.Value).ToList();for(int offset=0;offset<clauses.Count;offset+=100)bodies.Add(Templates.Expand("$PROVINCES{ "+String.Join(" ",clauses.Skip(offset).Take(100))+" }","ck3t_context_player"));}else bodies.Add(Templates.Body(f,amount,key,province));
   int steps=bodies.Count*(f.repeat?amount:1),step=0;foreach(int pass in Enumerable.Range(0,f.repeat?amount:1))foreach(string body in bodies){Check();step++;if(Progress!=null)Progress(f.title+Lang.T(" · пакет ")+step+" / "+steps);var reply=await Send(body+" "+Templates.Flush,id);if((f.id=="building" || f.id=="special") && !reply.Rows("CK3T_BUILD_APPLIED").Any())throw new InvalidOperationException(Lang.T("Провинция вне выбранного охвата. Постройка не добавлена."));}
  }finally{await CleanContext();}
 }
 public void ApplyNative(){if(Protection==null && nativeSets.Count>0)Protection=new NativeProtection(Bridge);if(Protection!=null)Protection.Set(nativeSets.Values.SelectMany(x=>x));}
 void ReplaceNativeSet(string key,uint[] next){uint[] prior;bool had=nativeSets.TryGetValue(key,out prior);if(next.Length==0)nativeSets.Remove(key);else nativeSets[key]=next;try{ApplyNative();}catch{if(had)nativeSets[key]=prior;else nativeSets.Remove(key);throw;}}
 public void SetStoryProtection(string name,IEnumerable<uint> people){ReplaceNativeSet("native_story_"+name,people.Distinct().ToArray());}
 public void ProtectCharacters(IEnumerable<uint> ids,bool on){uint[] prior;if(!nativeSets.TryGetValue("native_custom",out prior))prior=new uint[0];var next=on?prior.Union(ids).ToArray():prior.Except(ids).ToArray();ReplaceNativeSet("native_custom",next);if(next.Length==0)Active.Remove("native_custom");else Active.Add("native_custom");}
 public async Task Clear(bool stopStories=true){Bridge.Refresh();if(stopStories && Campaign!=null)await Campaign.Stories.StopAll();nativeSets.Clear();if(Sieges!=null){if(Sieges.AttachedGameState!=Bridge.GameState){Sieges.Dispose();Sieges=new NativeSieges(Bridge);}else Sieges.Clear();}if(CultureHeads!=null)await CultureHeads.Clear();if(WarScores!=null){if(WarScores.AttachedGameState!=Bridge.GameState){WarScores.Dispose();WarScores=new NativeWarScores(Bridge);}else WarScores.Clear();}if(Protection!=null){if(Protection.AttachedGameState!=Bridge.GameState){Protection.Dispose();Protection=null;}else Protection.Set(new uint[0]);}string register="if = { limit = { NOT = { has_global_variable_list = ck3t_dirty } } add_to_global_variable_list = { name = ck3t_dirty target = this } remove_list_global_variable = { name = ck3t_dirty target = this } } ";foreach(var f in Switches)foreach(string prefix in new[]{"ck3t_active_","ck3t_next_"})register+="if = { limit = { NOT = { has_global_variable_list = "+prefix+f.id+" } } add_to_global_variable_list = { name = "+prefix+f.id+" target = this } remove_list_global_variable = { name = "+prefix+f.id+" target = this } } ";await Send(register,Bridge.PlayerID);
  var items=Switches.ToList();for(int i=0;i<items.Count;i+=20)await Send(String.Join(" ",items.Skip(i).Take(20).Select(Templates.Disable)),Bridge.PlayerID);await Send(Templates.Flush+" remove_global_variable = ck3t_context_player remove_global_variable = ck3t_context_other",Bridge.PlayerID);Active.Clear();
 }
 public async Task Renew(){Check();if(Sieges!=null && Sieges.Count>0)Sieges.Prune();if(CultureHeads!=null && CultureHeads.Count>0)await CultureHeads.Tick();if(WarScores!=null && WarScores.Count>0)WarScores.Prune();if(Campaign!=null)await Campaign.Stories.Tick();if(Active.Count==0)return;if(nativeSets.ContainsKey("native_family")){await ReadSnapshot(false);ReplaceNativeSet("native_family",State.People.Where(p=>new[]{"Мой правитель","Супруг","Ребёнок"}.Contains(p.Role)).Select(p=>p.ID).ToArray());}if(nativeSets.Count>0)ApplyNative();LastNew=LastRecalculations=LastCommands=0;var dynamic=Switches.Where(f=>Active.Contains(f.id) && (new[]{"family","counties","provinces","commanders","knights","rulers"}.Contains(f.scope) || f.kind=="guard")).ToList();if(dynamic.Count==0)return;
  await Send("set_global_variable = { name = ck3t_context_player value = this }",State.Player);try{for(int i=0;i<dynamic.Count;i+=10)await Send(String.Join(" ",dynamic.Skip(i).Take(10).Select(f=>Templates.Reconcile(f)+" "+GuardMaintenance(f,true))),State.Player);await Send(Templates.Flush,State.Player);}finally{await CleanContext();}
